fields.script:
/**
 * 23-Enforce booking cutoff
 *
 * Aborts a reservation when the start date is in the past, or when the booking
 * was placed after the cutoff time configured on that calendar day.
 * Reception staff and admins may still book after the cutoff.
 */
(function executeRule(current, previous) {
    if (!current.isNewRecord() && !current.start_date.changes()) {
        return;
    }

    var startDate = current.getValue('start_date');
    if (!startDate) {
        return;
    }

    var today = new GlideDateTime(gs.beginningOfToday());
    var start = new GlideDateTime(startDate);
    if (start.getValue() < today.getValue()) {
        gs.addErrorMessage('Bookings cannot start in the past. Choose ' + gs.dateFormat(today, 'yyyy-MM-dd') + ' or later.');
        current.setAbortAction(true);
        return;
    }

    var calDay = new GlideRecord('x_2203703_car_re_0_cal_day');
    calDay.addQuery('date', '=', gs.dateFormat(start, 'yyyy-MM-dd'));
    calDay.query();
    if (!calDay.next()) {
        return; // not on the calendar: the business-day rule reports it
    }

    var cutoff = calDay.getValue('cutoff_time');
    if (!cutoff) {
        return;
    }

    var roles = gs.getUser().getRoles();
    for (var i = 0; i < roles.length; i++) {
        if (roles[i] == 'x_2203703_car_re_0.receptionist' || roles[i] == 'x_2203703_car_re_0.admin') {
            return; // staff may book after the cutoff
        }
    }

    var closeAt = new GlideDateTime(startDate + ' ' + cutoff);
    if (new GlideDateTime().getValue() >= closeAt.getValue()) {
        gs.addErrorMessage('Bookings for ' + gs.dateFormat(start, 'yyyy-MM-dd') + ' closed at ' + cutoff + '. Please choose a later business day.');
        current.setAbortAction(true);
    }
})(current, previous);

(function() {
  var CAR_TABLE = 'x_2203703_car_re_0_car';
  var RES_TABLE = 'x_2203703_car_re_0_reservation';
  var CAL_TABLE = 'x_2203703_car_re_0_cal_day';
  var DEFAULT_CUTOFF = '15:00';

  data.isGuest = !gs.isLoggedIn();
  data.durations = [
    { value: 'daily', label: 'Daily' },
    { value: 'weekly', label: 'Weekly' },
    { value: 'monthly', label: 'Monthly' }
  ];
  data.min_date = gs.dateFormat(gs.beginningOfToday(), 'yyyy-MM-dd');

  function rentOf(gr) {
    var r = String(gr.getValue('rent') || '0');
    if (r.indexOf(';') > -1) r = r.split(';')[1];
    return parseFloat(r) || 0;
  }

  function isStaff() {
    var roles = gs.getUser().getRoles();
    for (var i = 0; i < roles.length; i++) {
      if (roles[i] == 'x_2203703_car_re_0.receptionist' || roles[i] == 'x_2203703_car_re_0.admin') {
        return true;
      }
    }
    return false;
  }

  data.business_days = [];
  data.holidays = [];
  var cal = new GlideRecord(CAL_TABLE);
  cal.addQuery('date', '>=', data.min_date);
  cal.orderBy('date');
  cal.query();
  while (cal.next()) {
    var day = {
      date: gs.dateFormat(cal.getValue('date'), 'yyyy-MM-dd'),
      type: cal.getValue('day_type'),
      label: cal.getValue('label') || '',
      cutoff: cal.getValue('cutoff_time') || DEFAULT_CUTOFF
    };
    if (day.type == 'holiday') {
      data.holidays.push(day);
    } else {
      data.business_days.push(day);
    }
  }
  data.next_bookable_date = data.business_days.length ? data.business_days[0].date : '';

  function dayFor(date) {
    var i;
    for (i = 0; i < data.business_days.length; i++) {
      if (data.business_days[i].date == date) return data.business_days[i];
    }
    for (i = 0; i < data.holidays.length; i++) {
      if (data.holidays[i].date == date) return data.holidays[i];
    }
    return null;
  }

  function validate(f) {
    if (!f.car) return 'Please choose a car.';
    var car = new GlideRecord(CAR_TABLE);
    if (!car.get(f.car) || car.getValue('available') != '1')
      return 'That car is not available.';

    if (['daily', 'weekly', 'monthly'].indexOf(f.rental_duration) < 0)
      return 'Please choose a rental duration.';

    if (!f.start_date || !f.end_date) return 'Please enter both dates.';
    if (f.end_date < f.start_date) return 'The end date cannot be before the start date.';
    var today = new GlideDateTime().getLocalDate().getValue();
    if (f.start_date < today) return 'The start date cannot be in the past.';

    var day = dayFor(f.start_date);
    if (!day) {
      return 'Bookings can only start on a registered business day. ' + f.start_date + ' is not on the rental calendar.';
    }
    if (day.type == 'holiday') {
      return 'Bookings are not allowed on ' + f.start_date + ' because it is marked as a holiday' + (day.label ? ' (' + day.label + ')' : '') + '.';
    }
    if (day.cutoff && !isStaff()) {
      var closeAt = new GlideDateTime(f.start_date + ' ' + day.cutoff);
      if (new GlideDateTime().getValue() >= closeAt.getValue()) {
        return 'Bookings for ' + f.start_date + ' closed at ' + day.cutoff + '. Please choose a later business day.';
      }
    }

    if (!f.driver_name || !f.drivers_license)
      return "The driver's name and license are required.";

    if (data.isGuest && (!f.guest_name || !f.guest_email || !f.guest_contact_number))
      return 'Please enter your name, email and contact number.';

    return '';
  }

  if (input && input.action == 'submit') {
    var f = input.form || {};
    var err = validate(f);
    if (err) {
      data.error = err;
      return;
    }

    var gr = new GlideRecord(RES_TABLE);
    gr.initialize();
    gr.setValue('car', f.car);
    gr.setValue('rental_duration', f.rental_duration);
    gr.setValue('start_date', f.start_date);
    gr.setValue('end_date', f.end_date);
    gr.setValue('driver_name', f.driver_name);
    gr.setValue('drivers_license', f.drivers_license);
    gr.setValue('remarks', f.remarks || '');
    gr.setValue('state', 'reserved');

    if (data.isGuest) {
      gr.setValue('client_type', 'guest');
      gr.setValue('guest_name', f.guest_name);
      gr.setValue('guest_email', f.guest_email);
      gr.setValue('guest_contact_number', f.guest_contact_number);
    } else {
      gr.setValue('client_type', 'patron');
      gr.setValue('applicant', gs.getUserID());
    }

    var id = gr.insert();
    if (id) {
      data.success = 'Your reservation has been saved. We will see you on ' + f.start_date + '.';
    } else {
      data.error = 'The reservation could not be saved. Check the dates, or contact the front desk.';
    }
    return;
  }

  data.cars = [];
  var car = new GlideRecord(CAR_TABLE);
  car.addQuery('available', true);
  car.orderBy('name');
  car.query();
  while (car.next()) {
    data.cars.push({
      sys_id: car.getUniqueValue(),
      name: car.getValue('name'),
      type: car.getDisplayValue('type'),
      rent_value: rentOf(car)
    });
  }
  data.preselected = $sp.getParameter('car') || '';
})();

fields.client_script:
api.controller = function($window) {
  var c = this;

  c.form = {
    car: c.data.preselected || '',
    rental_duration: 'daily',
    start_date: null,
    end_date: null,
    driver_name: '',
    drivers_license: '',
    remarks: '',
    guest_name: '',
    guest_email: '',
    guest_contact_number: ''
  };
  c.error = '';
  c.success = '';
  c.busy = false;

  function pad(n) { return n < 10 ? '0' + n : '' + n; }
  function fmt(d) {
    return d ? d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) : '';
  }

  c.days = function() {
    if (!c.form.start_date || !c.form.end_date) return 0;
    var diff = Math.round((c.form.end_date - c.form.start_date) / 86400000) + 1;
    return diff > 0 ? diff : 0;
  };

  c.total = function() {
    var rent = 0;
    for (var i = 0; i < c.data.cars.length; i++) {
      if (c.data.cars[i].sys_id == c.form.car) rent = c.data.cars[i].rent_value;
    }
    return rent * c.days();
  };

  c.startDateIssue = function() {
    var d = fmt(c.form.start_date);
    if (!d) return '';
    var i;
    for (i = 0; i < (c.data.business_days || []).length; i++) {
      if (c.data.business_days[i].date == d) return '';
    }
    for (i = 0; i < (c.data.holidays || []).length; i++) {
      if (c.data.holidays[i].date == d) {
        return d + ' is a holiday' + (c.data.holidays[i].label ? ' (' + c.data.holidays[i].label + ')' : '') + ' and cannot be booked.';
      }
    }
    return d + ' is not a registered business day.';
  };

  c.submit = function() {
    c.error = '';
    c.success = '';
    if (!c.form.car || !c.form.start_date || !c.form.end_date) {
      c.error = 'Please choose a car and both dates.';
      return;
    }
    var issue = c.startDateIssue();
    if (issue) {
      c.error = issue;
      return;
    }
    if (!$window.confirm('The estimated rent is ' + c.total().toFixed(2) + '. Continue with the reservation?'))
      return;

    var payload = angular.copy(c.form);
    payload.start_date = fmt(c.form.start_date);
    payload.end_date = fmt(c.form.end_date);

    c.busy = true;
    c.server.get({ action: 'submit', form: payload }).then(function(r) {
      c.busy = false;
      if (r.data.error) {
        c.error = r.data.error;
      } else if (r.data.success) {
        c.success = r.data.success;
        c.form.start_date = null;
        c.form.end_date = null;
        c.form.remarks = '';
      }
    });
  };
};

