api.controller = function($window) {
  var c = this;
  c.form = {
    car: c.data.preselected || '', rental_duration: 'daily', start_date: null, end_date: null,
    driver_name: '', drivers_license: '', remarks: '', guest_name: '', guest_email: '', guest_contact_number: ''
  };
  c.error = ''; c.success = ''; c.busy = false;

  function pad(n) { return n < 10 ? '0' + n : '' + n; }
  function fmt(d) { return d ? d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) : ''; }

  c.days = function() {
    if (!c.form.start_date || !c.form.end_date) return 0;
    var diff = Math.round((c.form.end_date - c.form.start_date) / 86400000) + 1;
    return diff > 0 ? diff : 0;
  };
  c.total = function() {
    var rent = 0;
    for (var i = 0; i < c.data.cars.length; i++) if (c.data.cars[i].sys_id == c.form.car) rent = c.data.cars[i].rent_value;
    return rent * c.days();
  };
  c.busyRanges = function() {
    var out = [];
    if (!c.form.car) return out;
    for (var i = 0; i < (c.data.bookings || []).length; i++)
      if (c.data.bookings[i].car == c.form.car) out.push(c.data.bookings[i]);
    return out;
  };
  c.startDateIssue = function() {
    var d = fmt(c.form.start_date);
    if (!d) return '';
    var i;
    for (i = 0; i < (c.data.business_days || []).length; i++) if (c.data.business_days[i].date == d) return '';
    for (i = 0; i < (c.data.holidays || []).length; i++)
      if (c.data.holidays[i].date == d)
        return d + ' is a holiday' + (c.data.holidays[i].label ? ' (' + c.data.holidays[i].label + ')' : '') + ' and cannot be booked.';
    return d + ' is not a registered business day.';
  };
  c.overlapIssue = function() {
    var s = fmt(c.form.start_date);
    if (!s || !c.form.car) return '';
    var e = fmt(c.form.end_date) || s;
    var rs = c.busyRanges();
    for (var i = 0; i < rs.length; i++)
      if (rs[i].start <= e && rs[i].end >= s)
        return 'This car is already reserved ' + rs[i].start + ' to ' + rs[i].end + '.';
    return '';
  };
  c.submit = function() {
    c.error = ''; c.success = '';
    if (!c.form.car || !c.form.start_date || !c.form.end_date) { c.error = 'Please choose a car and both dates.'; return; }
    var issue = c.startDateIssue();
    if (issue) { c.error = issue; return; }
    var overlap = c.overlapIssue();
    if (overlap) { c.error = overlap; return; }
    if (!$window.confirm('The estimated rent is ' + c.total().toFixed(2) + '. Continue with the reservation?')) return;
    var payload = angular.copy(c.form);
    payload.start_date = fmt(c.form.start_date);
    payload.end_date = fmt(c.form.end_date);
    c.busy = true;
    c.server.get({ action: 'submit', form: payload }).then(function(r) {
      c.busy = false;
      if (r.data.error) c.error = r.data.error;
      else if (r.data.success) { c.success = r.data.success; c.form.start_date = null; c.form.end_date = null; c.form.remarks = ''; }
    });
  };
};

