(function() {
  var CAR_TABLE = 'x_2203703_car_re_0_car';
  var RES_TABLE = 'x_2203703_car_re_0_reservation';
  var today = gs.dateFormat(gs.beginningOfToday(), 'yyyy-MM-dd');
  data.today = today;

  var bookings = {};
  var bg = new GlideRecord(RES_TABLE);
  bg.addQuery('state', 'reserved');
  bg.addEncodedQuery('end_date>=' + today + '^ORend_dateISEMPTY');
  bg.orderBy('start_date');
  bg.query();
  while (bg.next()) {
    var cid = bg.getValue('car');
    if (!cid) continue;
    var s = gs.dateFormat(bg.getValue('start_date'), 'yyyy-MM-dd');
    var e = gs.dateFormat(bg.getValue('end_date') || bg.getValue('start_date'), 'yyyy-MM-dd');
    if (!bookings[cid]) bookings[cid] = [];
    bookings[cid].push({ start: s, end: e });
  }

  function nextFree(list) {
    var cursor = today;
    for (var i = 0; i < list.length; i++) {
      if (list[i].start <= cursor && list[i].end >= cursor) {
        var g = new GlideDateTime(list[i].end);
        g.addDaysUTC(1);
        cursor = g.getByFormat('yyyy-MM-dd');
      }
    }
    return cursor;
  }

  data.cars = [];
  var gr = new GlideRecord(CAR_TABLE);
  gr.orderBy('name');
  gr.query();
  while (gr.next()) {
    var id = gr.getUniqueValue();
    var b = bookings[id] || [];
    data.cars.push({
      sys_id: id,
      name: gr.getValue('name'),
      type: gr.getDisplayValue('type'),
      type_key: gr.getValue('type') || '',
      seats: gr.getValue('seating_capacity'),
      rent: gr.getDisplayValue('rent'),
      desc: gr.getValue('description') || '',
      available: gr.getValue('available') == '1',
      bookings: b.slice(0, 3),
      more: Math.max(0, b.length - 3),
      next_free: b.length ? nextFree(b) : today
    });
  }
})();

