(function() {
  var CAR_TABLE = 'x_2203703_car_re_0_car';
  var RES_TABLE = 'x_2203703_car_re_0_reservation';
  var CAL_TABLE = 'x_2203703_car_re_0_cal_day';
  var today = gs.dateFormat(gs.beginningOfToday(), 'yyyy-MM-dd');
  var todayEnd = gs.dateFormat(gs.endOfToday(), 'yyyy-MM-dd');
  data.today = today;

  data.cars = [];
  var available = 0;
  var car = new GlideRecord(CAR_TABLE);
  car.orderBy('name');
  car.query();
  while (car.next()) {
    var isAvail = car.getValue('available') == '1';
    if (isAvail) available++;
    data.cars.push({
      name: car.getValue('name'),
      type: car.getDisplayValue('type'),
      seats: car.getValue('seating_capacity'),
      rent: car.getDisplayValue('rent') || '',
      available: isAvail
    });
  }
  data.total_cars = data.cars.length;
  data.available_cars = available;

  var active = 0;
  var outToday = 0;
  var res = new GlideRecord(RES_TABLE);
  res.addQuery('state', 'reserved');
  res.query();
  while (res.next()) {
    active++;
    var s = res.getValue('start_date');
    var e = res.getValue('end_date');
    if (s && e && s <= todayEnd && e >= today) outToday++;
  }
  data.active_reservations = active;
  data.out_today = outToday;

  data.business_days = [];
  data.holidays = [];
  data.calendar = [];
  var cal = new GlideRecord(CAL_TABLE);
  cal.addQuery('date', '>=', today);
  cal.orderBy('date');
  cal.query();
  while (cal.next()) {
    var entry = {
      date: gs.dateFormat(cal.getValue('date'), 'yyyy-MM-dd'),
      type: cal.getValue('day_type'),
      label: cal.getValue('label') || '',
      cutoff: cal.getValue('cutoff_time') || ''
    };
    data.calendar.push(entry);
    if (entry.type == 'holiday') data.holidays.push(entry); else data.business_days.push(entry);
  }
})();

