api.controller = function() {
  var c = this;
  c.type = 'all';
  c.onlyFree = false;
  c.view = [];
  c.typeList = [];

  c.filter = function() {
    var out = [];
    var cars = c.data.cars || [];
    for (var i = 0; i < cars.length; i++) {
      var x = cars[i];
      if (c.type !== 'all' && x.type_key !== c.type) continue;
      if (c.onlyFree && !x.available) continue;
      out.push(x);
    }
    c.view = out;
  };

  c.setType = function(t) { c.type = t; c.filter(); };
  c.toggleFree = function() { c.onlyFree = !c.onlyFree; c.filter(); };

  var seen = {};
  for (var i = 0; i < (c.data.cars || []).length; i++) {
    var k = c.data.cars[i].type_key;
    if (k && !seen[k]) { seen[k] = 1; c.typeList.push(k); }
  }
  c.typeList.sort();
  c.filter();
};

