fields.script:
(function() {
  var CAR_TABLE = 'x_2203703_car_re_0_car';
  var RES_TABLE = 'x_2203703_car_re_0_reservation';

  data.cars = [];
  data.err = '';

  var today = new GlideDateTime().getLocalDate().getValue().substring(0, 10);
  data.today = today;

  function fmtDate(v) {
    if (!v) return '';
    var s = String(v);
    return s.length > 10 ? s.substring(0, 10) : s;
  }

  function nextFree(list) {
    var cursor = today;
    for (var i = 0; i < list.length; i++) {
      if (list[i].start <= cursor && list[i].end >= cursor) {
        var d = new GlideDateTime(list[i].end + ' 00:00:00');
        d.addDaysUTC(1);
        cursor = d.getLocalDate().getValue().substring(0, 10);
      }
    }
    return cursor;
  }

  try {
    var bookings = {};
    var bg = new GlideRecord(RES_TABLE);
    bg.addQuery('state', 'reserved');
    bg.addQuery('end_date', '>=', today);
    bg.orderBy('start_date');
    bg.query();
    while (bg.next()) {
      var cid = bg.getValue('car');
      if (!cid) continue;
      if (!bookings[cid]) bookings[cid] = [];
      bookings[cid].push({
        start: fmtDate(bg.getValue('start_date')),
        end: fmtDate(bg.getValue('end_date') || bg.getValue('start_date'))
      });
    }

    var gr = new GlideRecord(CAR_TABLE);
    gr.orderBy('name');
    gr.query();
    while (gr.next()) {
      var id = gr.getUniqueValue();
      var b = bookings[id] || [];
      var av = String(gr.getValue('available'));
      data.cars.push({
        sys_id: id,
        name: String(gr.getValue('name') || ''),
        type: String(gr.getDisplayValue('type') || ''),
        type_key: String(gr.getValue('type') || ''),
        seats: String(gr.getValue('seating_capacity') || ''),
        rent: String(gr.getDisplayValue('rent') || ''),
        desc: String(gr.getValue('description') || ''),
        available: (av == '1' || av == 'true'),
        bookings: b.slice(0, 3),
        more: Math.max(0, b.length - 3),
        next_free: b.length ? nextFree(b) : today
      });
    }
  } catch (e) {
    data.err = 'Could not load the fleet: ' + e.message;
    if (typeof gs !== 'undefined' && gs.error) gs.error('Car Availability: ' + e.message);
  }
})();

