fields.script:
(function() {
  var CAR_TABLE = 'x_2203703_car_re_0_car';
  var RES_TABLE = 'x_2203703_car_re_0_reservation';
  var CAL_TABLE = 'x_2203703_car_re_0_cal_day';
  var DEFAULT_CUTOFF = '15:00';

  data.cars = [];
  data.business_days = [];
  data.holidays = [];
  data.bookings = [];
  data.bookings_by_car = {};
  data.durations = [
    { value: 'daily', label: 'Daily' },
    { value: 'weekly', label: 'Weekly' },
    { value: 'monthly', label: 'Monthly' }
  ];
  data.err = '';
  data.preselected = '';

  function ymd(v) {
    if (!v) return '';
    var s = String(v);
    return s.length > 10 ? s.substring(0, 10) : s;
  }

  var today = new GlideDateTime().getLocalDate().getValue().substring(0, 10);
  data.min_date = today;
  data.isGuest = !gs.isLoggedIn();
  data.isStaff = gs.hasRole('x_2203703_car_re_0.receptionist') || gs.hasRole('x_2203703_car_re_0.admin');

  function rentOf(gr) {
    var r = String(gr.getValue('rent') || '0');
    if (r.indexOf(';') > -1) r = r.split(';')[1];
    return parseFloat(r) || 0;
  }

  function dayFor(date) {
    var i;
    for (i = 0; i < data.business_days.length; i++) if (data.business_days[i].date == date) return data.business_days[i];
    for (i = 0; i < data.holidays.length; i++) if (data.holidays[i].date == date) return data.holidays[i];
    return null;
  }

  function conflictFor(carId, start, end) {
    for (var i = 0; i < data.bookings.length; i++) {
      var b = data.bookings[i];
      if (b.car != carId) continue;
      if (b.start <= end && b.end >= start) return b;
    }
    return null;
  }

  function validate(f) {
    if (!f.car) return 'Please choose a car.';
    var car = new GlideRecord(CAR_TABLE);
    if (!car.get(f.car) || car.getValue('available') != '1') return 'That car is not available.';
    if (['daily', 'weekly', 'monthly'].indexOf(f.rental_duration) < 0) return 'Please choose a rental duration.';
    if (!f.start_date || !f.end_date) return 'Please enter both dates.';
    if (f.end_date < f.start_date) return 'The end date cannot be before the start date.';
    if (f.start_date < today) return 'The start date cannot be in the past.';

    var day = dayFor(f.start_date);
    if (!day) return 'Bookings can only start on a registered business day. ' + f.start_date + ' is not on the rental calendar.';
    if (day.type == 'holiday') return 'Bookings are not allowed on ' + f.start_date + ' because it is marked as a holiday' + (day.label ? ' (' + day.label + ')' : '') + '.';
    if (day.cutoff && !data.isStaff) {
      var closeAt = new GlideDateTime(f.start_date + ' ' + day.cutoff + ':00');
      if (new GlideDateTime().getValue() >= closeAt.getValue())
        return 'Bookings for ' + f.start_date + ' closed at ' + day.cutoff + '. Please choose a later business day.';
    }

    var conflict = conflictFor(f.car, f.start_date, f.end_date);
    if (conflict)
      return 'That car is already reserved from ' + conflict.start + ' to ' + conflict.end + '. Please choose another car or different dates.';

    if (!f.driver_name || !f.drivers_license) return "The driver's name and license are required.";
    if (data.isGuest && (!f.guest_name || !f.guest_email || !f.guest_contact_number))
      return 'Please enter your name, email and contact number.';
    return '';
  }

  try {
    var cal = new GlideRecord(CAL_TABLE);
    cal.addQuery('date', '>=', today);
    cal.orderBy('date');
    cal.query();
    while (cal.next()) {
      var day = {
        date: ymd(cal.getValue('date')),
        type: cal.getValue('day_type'),
        label: cal.getValue('label') || '',
        cutoff: cal.getValue('cutoff_time') || DEFAULT_CUTOFF
      };
      if (day.type == 'holiday') data.holidays.push(day);
      else data.business_days.push(day);
    }
    data.next_bookable_date = data.business_days.length ? data.business_days[0].date : '';

    var bg = new GlideRecord(RES_TABLE);
    bg.addQuery('state', 'reserved');
    bg.addQuery('end_date', '>=', today);
    bg.orderBy('start_date');
    bg.query();
    while (bg.next()) {
      var cid = bg.getValue('car');
      var rec = {
        car: cid,
        start: ymd(bg.getValue('start_date')),
        end: ymd(bg.getValue('end_date') || bg.getValue('start_date'))
      };
      data.bookings.push(rec);
      if (!cid) continue;
      if (!data.bookings_by_car[cid]) data.bookings_by_car[cid] = [];
      data.bookings_by_car[cid].push({ start: rec.start, end: rec.end });
    }

    if (input && input.action == 'submit') {
      var f = input.form || {};
      var err = validate(f);
      if (err) { data.error = err; return; }

      var gr = new GlideRecord(RES_TABLE);
      gr.initialize();
      gr.setValue('car', f.car);
      gr.setValue('rental_duration', f.rental_duration);
      gr.setValue('start_date', f.start_date);
      gr.setValue('end_date', f.end_date);
      gr.setValue('driver_name', f.driver_name);
      gr.setValue('drivers_license', f.drivers_license);
      gr.setValue('remarks', f.remarks || '');
      gr.setValue('state', 'reserved');

      if (data.isGuest) {
        gr.setValue('client_type', 'guest');
        gr.setValue('guest_name', f.guest_name);
        gr.setValue('guest_email', f.guest_email);
        gr.setValue('guest_contact_number', f.guest_contact_number);
      } else {
        gr.setValue('client_type', 'patron');
        gr.setValue('applicant', gs.getUserID());
      }

      var id = gr.insert();
      if (id) data.success = 'Reservation saved for ' + f.start_date + ' to ' + f.end_date + '.';
      else data.error = 'The reservation could not be saved. Check the dates, or contact the front desk.';
      return;
    }

    var car = new GlideRecord(CAR_TABLE);
    car.addQuery('available', true);
    car.orderBy('name');
    car.query();
    while (car.next()) {
      data.cars.push({
        sys_id: car.getUniqueValue(),
        name: String(car.getValue('name') || ''),
        type: String(car.getDisplayValue('type') || ''),
        rent_value: rentOf(car)
      });
    }

    try {
      var qp = $sp.getParameter('car');
      data.preselected = qp ? String(qp) : '';
    } catch (e2) { data.preselected = ''; }
  } catch (e) {
    data.err = 'Could not load the booking form: ' + e.message;
    if (typeof gs !== 'undefined' && gs.error) gs.error('Reserve a Car: ' + e.message);
  }
})();

