    { label: 'Admin console', id: 'admin_console' },
    { label: 'My reservations', id: 'my_reservations' }
  ];
})();

fields.css:
.cr-head{background:linear-gradient(120deg,#0e6b7d,#12889c);color:#fff;border-radius:14px;padding:22px 26px;margin-bottom:18px}
.cr-head h1{margin:0 0 4px;font-size:23px;font-weight:600;letter-spacing:-.01em;color:#fff}
.cr-head p{margin:0;font-size:13px;color:rgba(255,255,255,.82)}
.cr-card{background:#fff;border:1px solid #e3e8ee;border-radius:12px;padding:20px 22px;margin-bottom:16px}
.cr-card h3{margin:0 0 6px;font-size:16px;color:#16232e}
.cr-sub{color:#6b7c8a;font-size:13px;margin:0 0 14px}
.cr-alert{border-radius:10px;padding:11px 14px;font-size:13px;margin-bottom:14px}
.cr-alert-err{background:#fdeceb;color:#a13b32;border:1px solid #f3c9c4}
.cr-alert-ok{background:#eaf7ee;color:#1e7a45;border:1px solid #c6e7d1}
.cr-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;background:#0e6b7d;color:#fff;border:1px solid #0e6b7d;border-radius:8px;padding:9px 16px;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer;transition:background .15s,border-color .15s,box-shadow .15s}
.cr-btn:hover,.cr-btn:focus{background:#0b5766;border-color:#0b5766;color:#fff;text-decoration:none;box-shadow:0 2px 8px rgba(14,107,125,.22)}
.cr-btn-sm{padding:7px 13px;font-size:12px}
.cr-btn-ghost{background:#fff;color:#3f5261;border:1px solid #d4dde5}
.cr-btn-ghost:hover,.cr-btn-ghost:focus{background:#f4f7f9;border-color:#b7c4cf;color:#16232e;box-shadow:none}
.cr-btn-danger{background:#fff;color:#b3423a;border:1px solid #e6c2be}
.cr-btn-danger:hover,.cr-btn-danger:focus{background:#fdeceb;border-color:#d99b95;color:#932f28;box-shadow:none}
.cr-btn:disabled{opacity:.55;cursor:not-allowed;box-shadow:none}
.my-item{display:flex;justify-content:space-between;gap:16px;align-items:center;background:#fff;border:1px solid #e3e8ee;border-radius:12px;padding:16px 18px;margin-bottom:12px;transition:box-shadow .18s,border-color .18s}
.my-item:hover{box-shadow:0 8px 20px rgba(16,32,48,.08);border-color:#cfd9e2}
.my-main{min-width:0}
.my-top{display:flex;align-items:center;gap:10px;margin-bottom:8px}
.my-car{font-size:16px;color:#16232e}
.my-state{font-size:11px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;border-radius:999px;padding:3px 10px}
.my-state.is-reserved{background:#e6f3f6;color:#0f5c6b}
.my-state.is-closed{background:#e7f5ec;color:#1e7a45}
.my-state.is-cancelled{background:#f2f4f6;color:#7a8b99}
.my-meta{display:flex;flex-wrap:wrap;gap:18px;font-size:13px;color:#5a6b7a}
.my-k{color:#9aa9b6;font-size:11px;text-transform:uppercase;letter-spacing:.05em;margin-right:3px}
.my-actions{display:flex;gap:8px;flex-shrink:0;align-items:center}
.my-link{color:#0e6b7d;font-size:13px;font-weight:600;text-decoration:none;padding:7px 6px}
.my-link:hover{text-decoration:underline}
@media(max-width:680px){.my-item{flex-direction:column;align-items:stretch}.my-actions{justify-content:flex-end}}
